#include "lin_sim.h"
void lin_sim_respond(lin_slave_t *s,const lin_frame_t *q,lin_frame_t *r,bool *has,uint64_t now){if(has)*has=false;if(!s||!q||!r||!has||!s->present)return;if(q->id==0x3Cu||q->id==0x3Du)return;if(q->id!=s->node_id)return;uint8_t data[LIN_MAX_DATA]={0};data[0]=(uint8_t)(s->value&0xFFu);data[1]=(uint8_t)(s->value>>8);data[2]=s->kind==LIN_SLAVE_THERMAL?0xA1:s->last_command;if(lin_encode_frame(r,q->id,data,3,true)==LIN_OK){r->timestamp_us=now+s->response_delay_us;*has=true;}}
